#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum DType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Object,
}

impl DType {
    /// NumPy-like "kind" code.
    pub fn kind(self) -> char {
        match self {
            DType::Bool => 'b',
            DType::Int8 | DType::Int16 | DType::Int32 | DType::Int64 => 'i',
            DType::UInt8 | DType::UInt16 | DType::UInt32 | DType::UInt64 => 'u',
            DType::Float32 | DType::Float64 => 'f',
            DType::Complex64 | DType::Complex128 => 'c',
            DType::Object => 'O',
        }
    }

    /// Promotion precedence (larger means more general).
    pub fn precedence(self) -> u8 {
        match self {
            DType::Bool => 0,
            DType::Int8 => 1,
            DType::Int16 => 2,
            DType::Int32 => 3,
            DType::Int64 => 4,
            DType::UInt8 => 5,
            DType::UInt16 => 6,
            DType::UInt32 => 7,
            DType::UInt64 => 8,
            DType::Float32 => 9,
            DType::Float64 => 10,
            DType::Complex64 => 11,
            DType::Complex128 => 12,
            DType::Object => 13,
        }
    }
}

/// Task 1:
/// Given a non-empty collection of dtypes, return a dtype that appears in the
/// collection and whose precedence is at least as large as every dtype in it.
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    assert!(!types.is_empty(), "types must be non-empty");
    types
        .into_iter()
        .max_by_key(|t| t.precedence())
        .unwrap()
}

/// Task 2:
/// Determine the common dtype according to the described rules.
/// Returns None only if both input collections are empty.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    match (array_types.is_empty(), scalar_types.is_empty()) {
        (true, true) => None,
        (false, true) => Some(find_max_precedence_type(array_types)),
        (true, false) => Some(find_max_precedence_type(scalar_types)),
        (false, false) => {
            let amax = find_max_precedence_type(array_types);
            let smax = find_max_precedence_type(scalar_types);
            if amax.kind() == smax.kind() {
                Some(amax)
            } else {
                Some(smax)
            }
        }
    }
}